#![forbid(unsafe_code)]
//! Safe contracts whose boundary cases are checked by the package tests.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ByteView<'a> {
    bytes: &'a [u8],
}

impl<'a> ByteView<'a> {
    pub fn from_slice(bytes: &'a [u8]) -> Self {
        Self { bytes }
    }
    pub fn as_slice(&self) -> &[u8] {
        self.bytes
    }
}

pub fn split_regions(input: &mut [u8], at: usize) -> Option<(&mut [u8], &mut [u8])> {
    input.split_at_mut_checked(at)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RangeError {
    FirstInvalid,
    SecondInvalid,
    Overlap,
}

#[allow(clippy::needless_lifetimes)]
pub fn select_regions<'a>(
    buffer: &'a mut [u8],
    first: std::ops::Range<usize>,
    second: std::ops::Range<usize>,
) -> Result<(&'a mut [u8], &'a mut [u8]), RangeError> {
    if first.start > first.end || first.end > buffer.len() {
        return Err(RangeError::FirstInvalid);
    }
    if second.start > second.end || second.end > buffer.len() {
        return Err(RangeError::SecondInvalid);
    }
    if first.start < first.end
        && second.start < second.end
        && first.start < second.end
        && second.start < first.end
    {
        return Err(RangeError::Overlap);
    }
    if first.start == first.end && second.start == second.end {
        return Ok((&mut [], &mut []));
    }
    if first.start == first.end {
        let (_, tail) = buffer.split_at_mut(second.start);
        let (selected, _) = tail.split_at_mut(second.end - second.start);
        return Ok((&mut [], selected));
    }
    if second.start == second.end {
        let (_, tail) = buffer.split_at_mut(first.start);
        let (selected, _) = tail.split_at_mut(first.end - first.start);
        return Ok((selected, &mut []));
    }
    let first_is_low = first.start < second.start;
    let (low, high) = if first_is_low {
        (first, second)
    } else {
        (second, first)
    };
    let (_, tail) = buffer.split_at_mut(low.start);
    let (low_slice, after_low) = tail.split_at_mut(low.end - low.start);
    let (_, tail) = after_low.split_at_mut(high.start - low.end);
    let (high_slice, _) = tail.split_at_mut(high.end - high.start);
    if first_is_low {
        Ok((low_slice, high_slice))
    } else {
        Ok((high_slice, low_slice))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SlotState {
    Empty,
    Full,
}

pub struct Slot<T> {
    value: Option<T>,
}

impl<T> Slot<T> {
    pub fn empty() -> Self {
        Self { value: None }
    }
    pub fn put(&mut self, value: T) -> Result<(), T> {
        if self.value.is_some() {
            return Err(value);
        }
        self.value = Some(value);
        Ok(())
    }
    pub fn take(&mut self) -> Option<T> {
        self.value.take()
    }
    pub fn state(&self) -> SlotState {
        if self.value.is_some() {
            SlotState::Full
        } else {
            SlotState::Empty
        }
    }
    pub fn is_full(&self) -> bool {
        self.value.is_some()
    }
}

pub struct MutSlot<'a, T> {
    value: &'a mut T,
}

impl<'a, T> MutSlot<'a, T> {
    pub fn new(value: &'a mut T) -> Self {
        Self { value }
    }
    pub fn get(&self) -> &T {
        self.value
    }
    pub fn get_mut(&mut self) -> &mut T {
        self.value
    }
    pub fn reborrow(&mut self) -> MutSlot<'_, T> {
        MutSlot {
            value: &mut *self.value,
        }
    }
}

