#![allow(clippy::drop_non_drop, clippy::reversed_empty_ranges)]
use miri_safety_workshop::{
    ByteView, MutSlot, RangeError, Slot, SlotState, select_regions, split_regions,
};

#[test]
fn byte_view_borrows_initialized_bytes_without_owning_them() {
    let input = [10, 20];
    let view = ByteView::from_slice(&input);
    assert_eq!(view.as_slice(), &[10, 20]);
    assert_eq!(ByteView::from_slice(&[]).as_slice(), &[]);
}

#[test]
fn split_regions_are_disjoint() {
    let mut input = [1, 2, 3, 4];
    let (left, right) = split_regions(&mut input, 2).expect("valid split");
    left[0] = 9;
    right[0] = 8;
    assert_eq!(left, [9, 2]);
    assert_eq!(right, [8, 4]);
    assert!(split_regions(&mut input, 5).is_none());
}

#[test]
fn select_regions_accepts_empty_reversed_adjacent_and_gapped_ranges() {
    let mut input = [1_u8, 2, 3, 4, 5, 6];
    let (empty, whole) = select_regions(&mut input, 3..3, 0..6).expect("empty is valid");
    assert!(empty.is_empty());
    assert_eq!(whole, [1, 2, 3, 4, 5, 6]);
    drop((empty, whole));
    let base = input.as_mut_ptr();
    let (later, earlier) = select_regions(&mut input, 4..6, 1..3).expect("reversed order is valid");
    assert_eq!(later.as_ptr(), base.wrapping_add(4));
    assert_eq!(earlier.as_ptr(), base.wrapping_add(1));
    assert_eq!(later.len(), 2);
    assert_eq!(earlier.len(), 2);
    later[0] = 60;
    earlier[1] = 20;
    drop((later, earlier));
    assert_eq!(input, [1, 2, 20, 4, 60, 6]);
    assert!(select_regions(&mut input, 0..2, 2..4).is_ok());
    assert!(select_regions(&mut input, 0..1, 4..6).is_ok());
}

#[test]
fn select_regions_errors_have_precedence_and_preserve_the_buffer() {
    let mut input = [7_u8, 8, 9, 10];
    let before = input;
    assert_eq!(
        select_regions(&mut input, 4..3, 0..9),
        Err(RangeError::FirstInvalid)
    );
    assert_eq!(input, before);
    assert_eq!(
        select_regions(&mut input, 0..4, 4..3),
        Err(RangeError::SecondInvalid)
    );
    assert_eq!(input, before);
    assert_eq!(
        select_regions(&mut input, 0..3, 2..4),
        Err(RangeError::Overlap)
    );
    assert_eq!(input, before);
}

fn expected_select_result(
    length: usize,
    first: std::ops::Range<usize>,
    second: std::ops::Range<usize>,
) -> Result<(), RangeError> {
    if first.start > first.end || first.end > length {
        return Err(RangeError::FirstInvalid);
    }
    if second.start > second.end || second.end > length {
        return Err(RangeError::SecondInvalid);
    }
    if first.start < first.end
        && second.start < second.end
        && first.start < second.end
        && second.start < first.end
    {
        return Err(RangeError::Overlap);
    }
    Ok(())
}

fn check_select_case(length: usize, first: std::ops::Range<usize>, second: std::ops::Range<usize>) {
    let expected = expected_select_result(length, first.clone(), second.clone());
    let sentinel: Vec<u8> = (0..length).map(|index| 0xa0 + index as u8).collect();
    let mut data = sentinel.clone();
    match expected {
        Err(error) => {
            assert_eq!(select_regions(&mut data, first, second), Err(error));
            assert_eq!(data, sentinel, "errors must preserve every byte");
        }
        Ok(()) => {
            let first_len = first.end - first.start;
            let second_len = second.end - second.start;
            let before = data.clone();
            let first_pointer = if first_len > 0 {
                Some(data.as_ptr().wrapping_add(first.start))
            } else {
                None
            };
            let second_pointer = if second_len > 0 {
                Some(data.as_ptr().wrapping_add(second.start))
            } else {
                None
            };
            let (first_view, second_view) =
                select_regions(&mut data, first.clone(), second.clone()).expect("valid ranges");
            assert_eq!(first_view.len(), first_len);
            assert_eq!(second_view.len(), second_len);
            assert_eq!(first_view, &before[first.start..first.end]);
            assert_eq!(second_view, &before[second.start..second.end]);
            if first_len > 0 {
                assert_eq!(first_view.as_ptr(), first_pointer.unwrap());
            }
            if second_len > 0 {
                assert_eq!(second_view.as_ptr(), second_pointer.unwrap());
            }
            for (offset, byte) in first_view.iter_mut().enumerate() {
                *byte = 0x10 + offset as u8;
            }
            for (offset, byte) in second_view.iter_mut().enumerate() {
                *byte = 0x80 + offset as u8;
            }
            drop((first_view, second_view));
            for index in 0..length {
                let expected_byte = if first.start <= index && index < first.end {
                    0x10 + (index - first.start) as u8
                } else if second.start <= index && index < second.end {
                    0x80 + (index - second.start) as u8
                } else {
                    sentinel[index]
                };
                assert_eq!(data[index], expected_byte, "mutation at index {index}");
            }
        }
    }
}

#[test]
fn select_regions_exhaustive_endpoint_matrix() {
    let mut cases = 0_usize;
    for length in 0..=4 {
        for first_start in 0..=length + 1 {
            for first_end in 0..=length + 1 {
                for second_start in 0..=length + 1 {
                    for second_end in 0..=length + 1 {
                        cases += 1;
                        check_select_case(length, first_start..first_end, second_start..second_end);
                    }
                }
            }
        }
    }
    assert_eq!(cases, 2274);
}

#[test]
fn select_regions_handles_empty_orderings_and_shape_boundaries() {
    let mut data = [1_u8, 2, 3, 4];
    let (empty, whole) = select_regions(&mut data, 2..2, 0..4).unwrap();
    assert!(empty.is_empty());
    assert_eq!(whole, [1, 2, 3, 4]);
    drop((empty, whole));
    let (whole, empty) = select_regions(&mut data, 0..4, 2..2).unwrap();
    assert_eq!(whole, [1, 2, 3, 4]);
    assert!(empty.is_empty());
    drop((whole, empty));
    let (first_empty, second_empty) = select_regions(&mut data, 0..0, 4..4).unwrap();
    assert!(first_empty.is_empty() && second_empty.is_empty());
    drop((first_empty, second_empty));
    assert!(select_regions(&mut [], 0..0, 0..0).is_ok());
    assert!(select_regions(&mut data, 0..2, 2..4).is_ok());
    assert!(select_regions(&mut data, 0..1, 3..4).is_ok());
    assert!(select_regions(&mut data, 0..4, 4..4).is_ok());
    assert_eq!(
        select_regions(&mut data, 0..3, 2..4),
        Err(RangeError::Overlap)
    );
    assert_eq!(
        select_regions(&mut data, 0..3, 1..2),
        Err(RangeError::Overlap)
    );
    assert_eq!(
        select_regions(&mut data, 0..2, 1..4),
        Err(RangeError::Overlap)
    );
}

#[test]
fn select_regions_repeats_with_arbitrary_bytes_and_preserves_gaps() {
    let mut data = [0_u8, 255, 17, 128, 42, 99];
    for _ in 0..8 {
        let (first, second) = select_regions(&mut data, 1..2, 4..6).unwrap();
        assert_eq!(first, &[255]);
        assert_eq!(second, &[42, 99]);
        drop((first, second));
        data[2] = data[2].wrapping_add(1);
    }
    assert_eq!(data, [0, 255, 25, 128, 42, 99]);
}

#[test]
fn select_regions_rejects_extreme_endpoints_without_overflow() {
    let mut data = [4_u8, 5, 6];
    assert_eq!(
        select_regions(&mut data, usize::MAX..usize::MAX, 0..0),
        Err(RangeError::FirstInvalid)
    );
    assert_eq!(
        select_regions(&mut data, 0..0, usize::MAX..usize::MAX),
        Err(RangeError::SecondInvalid)
    );
    assert_eq!(
        select_regions(&mut data, usize::MAX..0, 0..0),
        Err(RangeError::FirstInvalid)
    );
    assert_eq!(
        select_regions(&mut data, 0..0, usize::MAX..0),
        Err(RangeError::SecondInvalid)
    );
    assert_eq!(data, [4, 5, 6]);
}

#[test]
fn slot_transfers_values_and_rejects_a_second_put() {
    let mut slot = Slot::empty();
    assert_eq!(slot.state(), SlotState::Empty);
    assert_eq!(slot.put(7_u32), Ok(()));
    assert_eq!(slot.state(), SlotState::Full);
    assert_eq!(slot.put(8_u32), Err(8));
    assert_eq!(slot.take(), Some(7));
    assert_eq!(slot.take(), None);
}

#[test]
fn mut_slot_reborrow_releases_the_outer_slot() {
    let mut value = 3;
    let mut slot = MutSlot::new(&mut value);
    {
        let mut short = slot.reborrow();
        *short.get_mut() += 1;
    }
    *slot.get_mut() += 2;
    assert_eq!(value, 6);
}

